// Compose each folder demo's `styles.css` from the shared fragment registry
// plus the demo's own `styles.json` manifest. The output is a real CSS file
// that App.vue imports, so Vite extracts it into the prerendered docs page
// (SSR-safe, no flash of unstyled content) and the playground's `?raw` glob
// seeds it into the REPL iframe. Generated files are gitignored; this runs in
// dev/build (package.json), as a Nuxt dev plugin (live reload, nuxt.config),
// and in the test setup (vitest.config) so every consumer resolves the import.
//
// Each demo's rules are confined to its own subtree by `scopeToDemo` (see
// below): the registry authors selectors under `.demo`, but a docs page hosts
// many demos and their lazily-injected stylesheets accumulate in one document
// across client-side navigation, so an unscoped `.demo button` would bleed
// onto a neighbour demo's controls. Keying every rule to a per-demo wrapper
// class closes that off.

import { readdirSync, existsSync, readFileSync, writeFileSync, rmSync } from 'node:fs'
import { dirname, resolve, join, basename } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { core, fragments } from './registry.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const demosDir = resolve(here, '../../docs-demos')

const FRAGMENT_NAMES = Object.keys(fragments)

const BANNER = `/* GENERATED by apps/site/scripts/demo-styles/codegen.mjs (do not edit).
   Composed from registry.mjs + this demo's styles.json ({ "with": [...] }).
   Regenerated on dev/build and gitignored. See ../README.md. */`

// Confine a composed stylesheet to one demo's own subtree. The registry
// authors every selector under `.demo` (the class each demo's root carries),
// but a docs page renders many demos at once and, on client-side navigation,
// their lazily-injected stylesheets accumulate in the document and are never
// removed. A bare `.demo button` rule from one demo would then cascade onto a
// neighbour's buttons. Inserting a per-demo wrapper class ahead of every
// `.demo` reference keys each rule to the single container that carries
// `.demo-<slug>` (DocsDemo's host element inline, the REPL's `#app` in the
// playground), so a demo's styles can only ever reach its own elements.
//
// The `.demo` token is kept in place (wrapper prepended, not renamed) so the
// wrapper reads as an ancestor. That preserves selectors which target the demo
// root itself (`.demo.layout`, `.dark .demo`) and descendant rules alike; a
// rename would break the root-compound and dark-mode forms.
function scopeToDemo(css, slug) {
  return css.replace(/\.demo(?![\w-])/g, `.demo-${slug} .demo`)
}

function composeCss(withList, slug) {
  const seen = new Set()
  for (const name of withList) {
    if (!(name in fragments)) {
      throw new Error(
        `[demo-styles] unknown fragment "${name}". ` +
          `Valid fragments: ${FRAGMENT_NAMES.join(', ')}.`
      )
    }
    seen.add(name)
  }
  const selected = FRAGMENT_NAMES.filter((name) => seen.has(name))
  const body = [core.trim(), ...selected.map((name) => fragments[name].trim())].join('\n\n')
  return [BANNER, scopeToDemo(body, slug)].join('\n\n') + '\n'
}

function readManifest(folder) {
  const manifestPath = join(folder, 'styles.json')
  // Read directly and treat ENOENT as "no manifest" rather than
  // existsSync-then-read, whose gap is a check-then-use file-system race.
  let raw
  try {
    raw = readFileSync(manifestPath, 'utf8')
  } catch (error) {
    if (error.code === 'ENOENT') return []
    throw new Error(`[demo-styles] ${manifestPath} could not be read: ${error.message}`)
  }
  let parsed
  try {
    parsed = JSON.parse(raw)
  } catch (error) {
    throw new Error(`[demo-styles] ${manifestPath} is not valid JSON: ${error.message}`)
  }
  const list = parsed?.with ?? []
  if (!Array.isArray(list) || list.some((name) => typeof name !== 'string')) {
    throw new Error(`[demo-styles] ${manifestPath}: "with" must be an array of fragment names.`)
  }
  return list
}

function writeIfChanged(file, content) {
  // Read-and-compare instead of existsSync-then-read-then-write: folding the
  // existence check into the read closes the check-then-use file-system race
  // CodeQL flags (js/file-system-race) while preserving the skip-identical
  // write that keeps codegen idempotent for the dev watcher.
  let existing
  try {
    existing = readFileSync(file, 'utf8')
  } catch {
    existing = undefined
  }
  if (existing === content) return false
  writeFileSync(file, content)
  return true
}

function demoFolders() {
  return readdirSync(demosDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => join(demosDir, entry.name))
    .filter((folder) => existsSync(join(folder, 'App.vue')))
}

// Regenerate a single demo folder's styles.css. Returns true if it changed.
// The folder name is the demo slug, which scopes every rule (see scopeToDemo)
// and must match the `.demo-<slug>` wrapper class DocsDemo / the REPL apply.
export function generateOne(folder) {
  if (!existsSync(join(folder, 'App.vue'))) return false
  return writeIfChanged(join(folder, 'styles.css'), composeCss(readManifest(folder), basename(folder)))
}

// Remove a styles.css stranded in a folder whose App.vue is gone (a deleted
// demo). Codegen only (re)writes styles.css for folders WITH an App.vue, so a
// stale sheet would otherwise linger unscoped: inert for the inline path (its
// glob keys on App.vue), but the playground's `*/*.{vue,ts,js,css}` glob would
// still match it and resolve `/demos/<slug>` to an entry-less playground.
// Pruning keeps the generated set in lockstep with the live demos. Returns the
// number of stale sheets removed.
function pruneOrphans() {
  let pruned = 0
  for (const entry of readdirSync(demosDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue
    const folder = join(demosDir, entry.name)
    if (existsSync(join(folder, 'App.vue'))) continue
    try {
      rmSync(join(folder, 'styles.css'))
      pruned++
    } catch (error) {
      if (error.code !== 'ENOENT') throw error
    }
  }
  return pruned
}

// Regenerate every folder demo. Returns a small summary for logging.
export function generateAll() {
  const folders = demoFolders()
  let written = 0
  for (const folder of folders) if (generateOne(folder)) written++
  const pruned = pruneOrphans()
  return { demos: folders.length, written, pruned }
}

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href
if (invokedDirectly) {
  const { demos, written, pruned } = generateAll()
  console.log(
    `[demo-styles] ${demos} demo(s) scanned, ${written} styles.css written, ${pruned} stale pruned.`
  )
}
